  coin() { this.tone(hz(96), 0.1, 'square', 0.16); this.tone(hz(100), 0.18, 'triangle', 0.14); }
  bell() { this.tone(hz(84), 1.1, 'sine', 0.2); this.tone(hz(88), 0.9, 'sine', 0.12, 4); this.tone(hz(91), 0.7, 'sine', 0.08, -4); }
