      }
      const bass = [[41, 45], [46, 50], [39, 43], [43, 47]][this.barIndex % 4];
      for (let i = 0; i < 4; i += 1) {
        this.musicNote(hz(bass[i % 2]), t + i * (bar / 4), 0.2, 'sine', 0.07);
