    ctx.strokeStyle = urgent && Math.sin(time * 14) > 0 ? '#e2564a' : col;
    ctx.beginPath();
    ctx.arc(x, y, r - 3, -Math.PI / 2, -Math.PI / 2 + t * Math.PI * 2);
    ctx.stroke();
    ctx.lineWidth = 1;
  }
